thread_local! {
    static HOST: Cell<Option<*mut (dyn Host + 'static)>> = const { Cell::new(None) };
}

/// Runs `f` with `host` installed for the calls it makes on this thread.
pub fn scope<R>(host: &mut dyn Host, f: impl FnOnce() -> R) -> R {
    // SAFETY: the pointer is removed again before `host` can be used elsewhere, and `with` only
    // dereferences it on this thread while this call is on the stack.
    let raw: *mut (dyn Host + 'static) = unsafe { std::mem::transmute(host as *mut dyn Host) };
    let previous = HOST.with(|slot| slot.replace(Some(raw)));
    struct Restore(Option<*mut (dyn Host + 'static)>);
    impl Drop for Restore {
        fn drop(&mut self) {
            HOST.with(|slot| slot.set(self.0));
        }
    }
    let _restore = Restore(previous);
    f()
}

#[cfg(not(target_arch = "wasm32"))]
fn with<R>(f: impl FnOnce(&mut dyn Host) -> R) -> R {
    match HOST.with(Cell::get) {
        // SAFETY: see `scope`.
        Some(raw) => f(unsafe { &mut *raw }),
        None => f(&mut Refusing),
    }
}
